import 'package:flutter/material.dart'; import 'package:flutter_riverpod/flutter_riverpod.dart'; import '../../core/api/api_client.dart'; import '../../core/api/models.dart';
final planProvider=FutureProvider<FinancialPlan>((ref)=>ref.watch(apiClientProvider).plan());
String money(int minor,String currency)=>'${(minor/100).toStringAsFixed(0)} $currency';
class TodayScreen extends ConsumerWidget{const TodayScreen({super.key});@override Widget build(BuildContext c,WidgetRef r)=>Scaffold(appBar:AppBar(title:const Text('Сегодня')),body:r.watch(planProvider).when(data:(p)=>ListView(padding:const EdgeInsets.all(24),children:[Text(p.action.title,style:Theme.of(c).textTheme.headlineMedium),Text(money(p.action.amount,p.currency)),const SizedBox(height:24),Text('Безопасно потратить: ${money(p.snapshot.safeToSpend,p.currency)}'),Text('В день: ${money(p.snapshot.safeDailyAmount,p.currency)}'),Text('Этап: ${p.state}')]),loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text(e.toString()))));}
